const temas=["Mapa de información", "Información y permisos", "Proveedores", "Seguridad y respuesta", "Aplicación y seguimiento"];const pasos=["Prepare un mapa de los datos que utiliza, sus finalidades, personas involucradas y responsables internos.", "Revise los avisos de privacidad y el fundamento que permite cada uso de datos.", "Identifique qué proveedores reciben o acceden a datos y revise las cláusulas aplicables.", "Defina quién gestiona accesos, solicitudes de las personas e incidentes, y cómo documentará la respuesta.", "Organice capacitación y una revisión de evidencias de aplicación."];
document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const values=temas.map((_,i)=>$('q'+i).value);const r=TempoTools.diagnostico(values);if(!r)return;const pending=r.filter(x=>x.value!=='si');show('<p class="eyebrow">Su próximo paso</p><h2>'+(pending.length?'Una agenda para revisar con su equipo':'Revise la evidencia de lo que ya aplica')+'</h2><p>'+(pending.length?'Estas respuestas señalan aspectos por aclarar o completar; no demuestran una infracción.':'Usted indica contar con medidas en los cinco puntos consultados. Hace falta revisar su alcance y evidencia para valorar el cumplimiento.')+'</p><ul>'+r.map(x=>'<li><strong>'+temas[x.index]+': </strong>'+(x.value==='si'?'Conserve y revise la evidencia que respalda su respuesta.':pasos[x.index])+(x.value==='nose'?' Empiece por confirmar qué existe actualmente.':'')+'</li>').join('')+'</ul><p>Esta orientación no determina si necesita un DPD ni si corresponde una evaluación de impacto. Puede revisar esas cuestiones con su asesor o con nuestra herramienta de DPD y gran escala.</p>'+finish());});